import{c as e,Q as a,j as o,m as i}from"./chunks/framework.COywXlYp.js";const h=JSON.parse('{"title":"开始使用","description":"","frontmatter":{"layout":"doc","title":"开始使用"},"headers":[],"relativePath":"zh-CN/guide/getting-started.md","filePath":"zh-CN/guide/getting-started.md"}'),s={name:"zh-CN/guide/getting-started.md"};function c(l,t,r,u,d,p){return a(),o("div",null,[...t[0]||(t[0]=[i('<h1 id="开始使用" tabindex="-1">开始使用 <a class="header-anchor" href="#开始使用" aria-label="Permalink to &quot;开始使用&quot;">​</a></h1><h2 id="下载安装" tabindex="-1">下载安装 <a class="header-anchor" href="#下载安装" aria-label="Permalink to &quot;下载安装&quot;">​</a></h2><p>前往<a href="https://github.com/xystudiocode/pyClickMouse/releases/latest" target="_blank" rel="noreferrer">github发布页面</a></p><p>选择<code>clickmouse.7z</code>，然后下载，下载完成后解压到当前目录</p><h2 id="运行" tabindex="-1">运行 <a class="header-anchor" href="#运行" aria-label="Permalink to &quot;运行&quot;">​</a></h2><h3 id="初始化" tabindex="-1">初始化 <a class="header-anchor" href="#初始化" aria-label="Permalink to &quot;初始化&quot;">​</a></h3><p>点击<code>解压后的文件夹/main.exe</code>，同意UAC弹窗，等待程序初始化完成。</p><p>先点击下一步，然后&quot;同意此协议&quot;，点击2次&quot;下一步&quot; <img class="license" alt="协议"></p><p>之后会让你选择是否创建快捷方式，建议创建，点击&quot;下一步&quot;</p><img class="shortcut" alt="创建快捷方式"><p>然后是选择包，你可以酌情选择，点击&quot;下一步&quot;，确认组件选择弹窗。</p><img class="compoments" alt="组件选择"><p>之后等待安装完成，进入安装完成提示页面，建议勾选&quot;运行clickmouse&quot;，点击&quot;完成&quot;</p><img class="finish" alt="安装完成"><h3 id="使用" tabindex="-1">使用 <a class="header-anchor" href="#使用" aria-label="Permalink to &quot;使用&quot;">​</a></h3><p>设置一个连点间隔和连点次数，连点输入框旁边的按钮可以设置单位</p><p>设置结束后，点击&quot;左键连点&quot;或者&quot;右键连点&quot;按钮，开始连点</p><blockquote><p>若是灰色，可以检查是否填入的是数字，clickmouse只检测整数数字</p></blockquote><p>点击&quot;停止&quot;按钮停止连点</p><p>点击&quot;暂停&quot;按钮可以暂停连点，然后你可以点击&quot;重启&quot;按钮继续连点</p><img class="clickmouse" alt="clickmouse运行图"><div class="tip custom-block"><p class="custom-block-title">提示</p><p>之后如果要运行，可以双击<code>解压后的文件夹/main.exe</code>运行程序，也可以右键点击桌面或开始菜单快捷方式运行</p></div>',22)])])}const q=e(s,[["render",c]]);export{h as __pageData,q as default};
